#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_height,
    int input_width,
    int kernel_height,
    int kernel_width,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int output_height,
    int output_width
) {
    int batch_idx = blockIdx.x;
    int out_ch_idx = blockIdx.y;
    int out_h_idx = blockIdx.z * blockDim.x + threadIdx.x;
    int out_w_idx = threadIdx.y;

    if (batch_idx >= batch_size || out_ch_idx >= out_channels || 
        out_h_idx >= output_height || out_w_idx >= output_width) {
        return;
    }

    // Initialize accumulator with zero
    float sum = 0.0f;

    // Perform convolution
    for (int ic = 0; ic < in_channels; ++ic) {
        for (int kh = 0; kh < kernel_height; ++kh) {
            for (int kw = 0; kw < kernel_width; ++kw) {
                int input_h = out_h_idx * stride_h - pad_h + kh;
                int input_w = out_w_idx * stride_w - pad_w + kw;

                // Check bounds
                if (input_h >= 0 && input_h < input_height && 
                    input_w >= 0 && input_w < input_width) {

                    int input_idx = batch_idx * (in_channels * input_height * input_width) +
                                   ic * (input_height * input_width) +
                                   input_h * input_width + input_w;

                    int weight_idx = out_ch_idx * (in_channels * kernel_height * kernel_width) +
                                    ic * (kernel_height * kernel_width) +
                                    kh * kernel_width + kw;

                    sum += __half2float(input[input_idx]) * __half2float(weight[weight_idx]);
                }
            }
        }
    }

    // Store result
    int output_idx = batch_idx * (out_channels * output_height * output_width) +
                     out_ch_idx * (output_height * output_width) +
                     out_h_idx * output_width + out_w_idx;

    output[output_idx] = __float2half(sum);
}

// Host wrapper function
extern "C" void launch_conv2d(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_height,
    int input_width,
    int kernel_height,
    int kernel_width,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int output_height,
    int output_width
) {
    dim3 grid_dim(batch_size, out_channels, (output_height + 31) / 32);
    dim3 block_dim(32, 32);

    conv2d_kernel<<<grid_dim, block_dim>>>(
        input, weight, output,
        batch_size, in_channels, out_channels,
        input_height, input_width,
        kernel_height, kernel_width,
        stride_h, stride_w,
        pad_h, pad_w,
        output_height, output_width
    );

    cudaDeviceSynchronize();
}
"""

# Load the CUDA extension
conv_module = load_inline(
    name="conv2d_cuda",
    cpp_sources="",
    cuda_sources=cuda_source,
    functions=["launch_conv2d"],
    verbose=True
)

class ModelNew(torch.nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = torch.nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        # Convert to fp16 if needed
        if x.dtype != torch.float16:
            x = x.to(torch.float16)

        # Get dimensions
        batch_size, _, height, width = x.shape

        # Extract weight and bias
        weight = self.conv1.weight.data.contiguous()
        bias = self.conv1.bias.data.contiguous() if self.conv1.bias is not None else None

        # Allocate output tensor
        output = torch.empty(
            batch_size, 
            self.conv1.out_channels, 
            (height + 2 * self.conv1.padding[0] - self.conv1.kernel_size[0]) // self.conv1.stride[0] + 1,
            (width + 2 * self.conv1.padding[1] - self.conv1.kernel_size[1]) // self.conv1.stride[1] + 1,
            dtype=torch.float16,
            device=x.device
        )

        # Launch CUDA kernel
        conv_module.launch_conv2d(
            x.data_ptr(),
            weight.data_ptr(),
            output.data_ptr(),
            batch_size,
            self.conv1.in_channels,
            self.conv1.out_channels,
            height,
            width,
            self.conv1.kernel_size[0],
            self.conv1.kernel_size[1],
            self.conv1.stride[0],
            self.conv1.stride[1],
            self.conv1.padding[0],
            self.conv1.padding[1],
            output.shape[2],
            output.shape[3]
        )

        # Add bias if present
        if bias is not None:
            # Bias addition broadcasted across spatial dimensions
            output = output + bias.view(1, -1, 1, 1)

        return output

